using System;using System.Collections.Generic;using System.IO;using System.Linq;using System.Text;using System.Windows;using System.Windows.Controls;using System.Windows.Media;using System.Windows.Media.Imaging;using System.Windows.Threading;
namespace SeraphimLuxury {
 static class OrbitalTests {
  static void Check(bool value,string message){if(!value)throw new Exception(message);}
  public static int Api(string endpoint,string directory){Directory.CreateDirectory(directory);try{Uri uri;if(!Uri.TryCreate(endpoint,UriKind.Absolute,out uri)||!uri.IsLoopback||uri.Scheme!="http")throw new Exception("Test uniquement sur un serveur local possédé.");LocalAssistant.Endpoint=endpoint;var models=LocalAssistant.Models().GetAwaiter().GetResult();Check(models.Contains("fixture-model"),"Lecture du catalogue local");var answer=LocalAssistant.Ask("fixture-model",new List<ChatTurn>{new ChatTurn {role="user",content="Bonjour, test local."}},System.Threading.CancellationToken.None).GetAwaiter().GetResult();Check(answer=="Réponse du serveur de test : aucun modèle réel utilisé.","Protocole local et texte de réponse");File.WriteAllText(Path.Combine(directory,"assistant-api-test.txt"),"PASS catalogue et échange HTTP Ollama compatible sur un serveur de test local. Aucune inférence IA réelle, aucun microphone et aucun historique personnel.\n");return 0;}catch(Exception e){File.WriteAllText(Path.Combine(directory,"assistant-api-test.txt"),"FAIL "+e);return 1;}}
  public static int News(string directory){Directory.CreateDirectory(directory);try{System.Net.ServicePointManager.SecurityProtocol=System.Net.SecurityProtocolType.Tls12;var rows=CountryNews.Load("Paris, France").GetAwaiter().GetResult();Check(rows.Count>0&&rows.All(i=>i.Url.StartsWith("https://")),"Flux réel HTTPS par ville");File.WriteAllText(Path.Combine(directory,"news-test.txt"),"PASS lecture publique en direct de "+rows.Count+" titres HTTPS pour Paris, France. Aucun article reproduit.\n");return 0;}catch(Exception e){File.WriteAllText(Path.Combine(directory,"news-test.txt"),"FAIL "+e);return 1;}}
  public static int Run(string directory){Directory.CreateDirectory(directory);var app=new Application {ShutdownMode=ShutdownMode.OnExplicitShutdown};var p=Preferences.Defaults();p.Premium=true;p.ReducedMotion=true;var store=new PreferenceStore(Path.Combine(directory,"preferences.json"));store.Save(p);var w=new MainWindow(store,true){Opacity=0,ShowInTaskbar=false};app.MainWindow=w;int stage=0;var log=new StringBuilder();var timer=new DispatcherTimer {Interval=TimeSpan.FromMilliseconds(250)};timer.Tick+=delegate {try{switch(stage++){
   case 0:w.UpdateLayout();w.Capture(Path.Combine(directory,"home.png"));w.atlas.SetGlobe(true);w.atlas.RotateGlobe(10,12);break;
   case 1:w.UpdateLayout();Branding.Capture(w.atlas,Path.Combine(directory,"globe-transparent.png"));w.Capture(Path.Combine(directory,"globe.png"));var bitmap=new BitmapImage(new Uri(Path.Combine(directory,"globe-transparent.png")));var converted=new FormatConvertedBitmap(bitmap,PixelFormats.Bgra32,null,0);byte[] pixels=new byte[converted.PixelWidth*converted.PixelHeight*4];converted.CopyPixels(pixels,converted.PixelWidth*4,0);Check(pixels[3]==0,"Le globe doit être transparent aux coins");Check(pixels.Where((v,i)=>i%4==3&&v>0).Count()>1000,"Le globe doit réellement être dessiné");w.atlas.RotateGlobe(95,-20);break;
   case 2:Branding.Capture(w.atlas,Path.Combine(directory,"globe-rotated.png"));Check(!File.ReadAllBytes(Path.Combine(directory,"globe-transparent.png")).SequenceEqual(File.ReadAllBytes(Path.Combine(directory,"globe-rotated.png"))),"La rotation modifie la projection");var cairo=AtlasPlaces.Data.cities.First(c=>c.id=="EGY-cairo");w.atlas.SelectCity(cairo,true);w.atlas.Seek(AtlasPlaces.PositionOf(500));Check(AtlasPlaces.Chapter(cairo,w.atlas.Selected,500).asset=="real-mary-egypt.jpg","Mémoire de Marie d’Égypte documentée");w.atlas.AircraftFlow=true;w.Capture(Path.Combine(directory,"globe-egypt.png"));log.AppendLine("PASS globe orthographique, rotation réelle, PNG transparent et mémoire de Marie d’Égypte.");w.ShowPage("Applications");break;
   case 3:w.Capture(Path.Combine(directory,"applications.png"));Check(ToolsTests.Descend(w.ToolsPage).OfType<ScrollViewer>().Any(),"Le catalogue compact doit défiler");w.OrbitalSeedCalendar();w.ShowPage("Calendrier");break;
   case 4:w.Capture(Path.Combine(directory,"calendar-month.png"));w.OrbitalWeek();break;
   case 5:w.Capture(Path.Combine(directory,"calendar-week.png"));w.ShowPage("Blacklist");var input=ToolsTests.Descend(w.ToolsPage).OfType<TextBox>().Single();input.Text="@test-createur\nnom: Auteur de test\nmot: terme-test\n@TEST-CREATEUR";ToolsTests.Descend(w.ToolsPage).OfType<Button>().Single(b=>System.Windows.Automation.AutomationProperties.GetName(b)=="Enregistrer la liste").RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Check(store.Load().Blacklist.Count==3,"La blacklist est enregistrée et dédupliquée");Check(w.OrbitalStatus().blacklist.Length==3,"Le pont reçoit la liste");w.Capture(Path.Combine(directory,"blacklist.png"));w.ShowPage("Apparence");break;
   case 6:w.Capture(Path.Combine(directory,"appearance.png"));Check(ToolsTests.Descend(w.ToolsPage).OfType<Image>().Count()>=4,"Concepts et Windows illustrés");w.ShowPage("IA");w.OrbitalAssistant();break;
   case 7:w.OrbitalAssistantCapture(Path.Combine(directory,"assistant.png"));var items=CountryNews.Parse("<rss><channel><item><title>Test &amp; titre</title><link>https://example.org/article</link><source>Source de test</source></item><item><title>Refus</title><link>javascript:alert(1)</link></item></channel></rss>");Check(items.Count==1&&items[0].Title=="Test & titre","Flux RSS et liens HTTPS seulement");bool rejected=false;try{CountryNews.Parse("<!DOCTYPE rss [<!ENTITY leak SYSTEM 'file:///C:/Windows/win.ini'>]><rss>&leak;</rss>");}catch(System.Xml.XmlException){rejected=true;}Check(rejected,"Aucun accès XML externe");log.AppendLine("PASS catalogue compact, vues calendrier mois/semaine, blacklist persistée et transmise, concepts Windows, assistant flottant et parsing RSS sûr.");log.AppendLine("PASS aucune modification d’apparence Windows ni utilisation de microphone pendant les essais.");timer.Stop();w.Close();File.WriteAllText(Path.Combine(directory,"orbital-test.txt"),log.ToString());app.Shutdown();break;
  }}catch(Exception e){timer.Stop();File.WriteAllText(Path.Combine(directory,"orbital-test.txt"),"FAIL stage "+stage+" "+e);w.Close();app.Shutdown(1);}};w.Loaded+=delegate{timer.Start();};return app.Run(w);}
 }
 partial class MainWindow {
  internal void OrbitalSeedCalendar(){selectedDay=new DateTime(2026,10,9);preferences.Calendar.Add(new CalendarEntry {Id="fixture",Title="Préparer mon projet",Date="2026-10-09",Time="14:30"});Planning.Get(preferences,selectedDay).Tasks.Add(new PlanTask {Id="fixture-task",Title="Avancer le projet",Time="10:00",Minutes=60});}
  internal void OrbitalWeek(){calendarMode=1;ShowCalendar();}
  internal BridgeResponse OrbitalStatus(){return BrowserRequest(new BridgeRequest {action="status"});}
  internal void OrbitalAssistant(){OpenAssistant();}
  internal void OrbitalAssistantCapture(string path){assistant.UpdateLayout();Branding.Capture((FrameworkElement)assistant.Content,path);assistant.Close();}
 }
}
